  "运行终端命令前需要你逐次批准。修改工作区外的文件前也需要批准；工作区内的文件修改无需逐次确认。": "터미널 명령을 실행하기 전에 매번 승인이 필요합니다. 워크스페이스 외부 파일을 수정할 때도 승인이 필요하며, 워크스페이스 내부 파일 수정은 건별 확인 없이 진행됩니다.",
  "先由当前对话选择的模型判断风险。只有风险操作或判断失败时才请求批准，低风险操作直接执行。": "먼저 현재 채팅에서 선택한 모델이 위험을 판단합니다. 위험한 작업이거나 판단에 실패한 경우에만 승인을 요청하며, 낮은 위험의 작업은 바로 실행합니다.",
  "在当前工具权限范围内执行命令和文件修改，不再逐项询问。": "현재 도구 권한 범위 내에서 명령 실행과 파일 수정을 수행하며, 항목마다 묻지 않습니다.",
  "此对话使用配方启动时的权限快照；应用默认权限不受影响。": "이 채팅은 레시피 실행 시점의 권한 스냅숏을 사용합니다. 앱 기본 권한에는 영향을 주지 않습니다.",
  "执行权限会影响 Agent 能自动完成的操作。「帮我批准」由当前对话选择的模型判断风险。": "실행 권한은 Agent가 자동으로 완료할 수 있는 작업에 영향을 줍니다. '자동 승인'은 현재 채팅에서 선택된 모델이 위험을 판단합니다.",
