  "副作用范围是配方声明；工作区与外部阶段仍使用原工具权限。只有已确认失败的只读阶段允许手动重试，结果不明或中断均不重放。": "부작용 범위는 레시피에서 선언한 값입니다. 워크스페이스 및 외부 단계는 기존 도구 권한을 계속 사용합니다. 실패가 확인된 읽기 전용 단계만 수동으로 재시도할 수 있으며, 결과가 불분명하거나 중단된 경우 다시 실행되지 않습니다.",
