  "团队配方库": "팀 레시피 라이브러리",
  "团队模板保存到项目的 .vela/team-task-recipes.json，可通过 Git 或共享目录同步。实际访问权限由仓库或文件系统控制；这里的写入开关只限制本机操作。仅共享模板，参数默认值与正文会共享，请勿填写凭据。运行参数、记录、评价与来源聊天不会共享。": "팀 템플릿은 프로젝트의 .vela/team-task-recipes.json에 저장되며 Git 또는 공유 폴더로 동기화할 수 있습니다. 실제 접근 권한은 저장소나 파일 시스템이 관리하며, 여기의 쓰기 설정은 이 클라이언트의 작업만 제한합니다. 템플릿 본문과 매개변수 기본값이 공유되므로 자격 증명을 포함하지 마세요. 실행 입력, 기록, 평가, 원본 채팅은 공유되지 않습니다.",
