  "工作区有未提交改动，执行前请先提交或暂存。": "작업 트리에 커밋되지 않은 변경 사항이 있습니다. 실행 전에 커밋하거나 스태시하세요.",
  "已存在撤销提交，重复执行会再产生一个撤销提交。": "되돌리기 커밋이 이미 있습니다. 다시 실행하면 되돌리기 커밋이 하나 더 만들어집니다.",
  "该提交已在当前分支历史中，重复拣选可能产生空提交或冲突。": "이 커밋은 이미 현재 브랜치 기록에 있습니다. 다시 체리픽하면 빈 커밋이나 충돌이 생길 수 있습니다.",
