  "活跃天数": "활동 일수",
  "已计量表示提供方返回了 Token 用量；覆盖率 = 已计量请求数 / 请求总数。分支对话复制的历史请求只计一次。": "계측됨은 제공자가 토큰 사용량을 반환했음을 의미합니다. 적용률 = 계측된 요청 수 / 전체 요청 수. 대화 분기로 복사된 기록 요청은 한 번만 계산합니다.",
  "统计当前对话中的模型请求。已计量表示提供方返回了 Token 用量；覆盖率 = 已计量请求数 / 请求总数。": "현재 대화의 모델 요청을 집계합니다. 계측됨은 제공자가 토큰 사용량을 반환했음을 의미합니다. 적용률 = 계측된 요청 수 / 전체 요청 수.",
  "{0} 个请求缺少日期，未计入活跃天数。": "날짜가 없는 요청 {0}건은 활동 일수에 포함되지 않습니다.",
