  "所选范围内没有思考内容总结请求。": "선택한 범위에 사고 내용 요약 요청이 없습니다.",
  "当前对话还没有思考内容总结请求。开启思考总结并完成一段思考后会在这里显示。": "현재 대화에는 아직 사고 내용 요약 요청이 없습니다. 사고 요약을 켜고 사고 과정을 마치면 여기에 표시됩니다.",
  "思考内容总结模型使用统计表": "사고 내용 요약 모델 사용 통계 표",
  "这些请求由思考内容总结功能发起，使用设置中指定的专属总结模型；未指定时使用发起总结时对话选定的模型。它们不计入其他标签页的请求与 Token 统计。": "이 요청은 사고 내용 요약 기능이 보내며, 설정에서 지정한 전용 요약 모델을 사용합니다. 지정하지 않은 경우 요약 시 대화에서 선택된 모델을 사용합니다. 다른 탭의 요청 및 토큰 통계에는 포함되지 않습니다.",
  "提供方使用统计表": "제공자 사용 통계 표",
