  "仅统计提供方上报的用量，不估算 Token。现有记录无法区分未上报与不支持，因此不支持显示为未知。": "제공자가 보고한 사용량만 집계하며 토큰은 추정하지 않습니다. 기존 기록으로는 미보고와 미지원을 구분할 수 없어 미지원은 알 수 없음으로 표시합니다.",
  "覆盖率反映请求的用量记录完整度。进行中或未返回用量的请求仍计入请求数；Token 总数仅汇总已计量请求。缓存命中率 = 缓存命中 Token / 输入 Token。": "적용률은 요청의 사용량 기록이 얼마나 갖춰졌는지를 나타냅니다. 진행 중이거나 사용량이 반환되지 않은 요청도 요청 수에 포함됩니다. 토큰 총계는 계측된 요청만 집계합니다. 캐시 적중률 = 캐시 적중 토큰 / 입력 토큰.",
