  "可设置 clientId、clientSecret、callbackPort、callbackUrl、scope、clientName、authServerMetadataUrl。留空保留原配置。": "clientId, clientSecret, callbackPort, callbackUrl, scope, clientName, authServerMetadataUrl을 설정할 수 있습니다. 비우면 기존 설정을 유지합니다.",
  "凭据已遮盖。编辑时留空保留原值；输入 {} 清除。": "자격 증명은 가려져 있습니다. 편집할 때 비워 두면 기존 값을 유지하며, {}를 입력하면 지웁니다.",
  "值必须是字符串。凭据不会显示在服务器列表中。": "값은 문자열이어야 합니다. 자격 증명은 서버 목록에 표시되지 않습니다.",
  "已保存的键": "저장된 키",
