  "按需发现：需要时加载工具；直接提供：始终加入工具列表；隐藏：不向 Agent 提供工具。": "필요 시 발견: 필요할 때 도구를 불러옵니다. 항상 제공: 도구 목록에 직접 추가합니다. 숨김: Agent에 도구를 제공하지 않습니다.",
  "已停用": "비활성화됨",
