  "重新连接": "다시 연결",
  "确认删除此配置？删除覆盖配置后可能恢复其他来源的同名服务器。": "이 구성을 삭제하시겠습니까? 재정의 구성을 삭제하면 다른 출처의 같은 이름 서버가 복원될 수 있습니다.",
  "保存服务器": "서버 저장",
  "正在保存": "저장 중",
  "已保存": "저장됨",
