  "目标已完成，验证记录中包含已知问题。请在最终回复中列出失败检查和依据。": "목표는 완료되었지만 검증 기록에 알려진 문제가 포함되어 있습니다. 최종 응답에 실패한 검사와 근거를 나열하세요.",
  "目标已完成，交付验证已记录。": "목표가 완료되었고 납품 검증이 기록되었습니다.",
  "目标仍在进行。{0}": "목표는 아직 진행 중입니다. {0}",
  "目标未处于进行中，不能更新验证记录。": "목표가 진행 중이 아니므로 검증 기록을 업데이트할 수 없습니다.",
  "已记录，含已知失败": "기록됨, 알려진 실패 포함",
