  "文件检查点": "파일 체크포인트",
  "每轮对话开始和结束时记录工作区文件，用于回到之前的状态。相同内容的文件只存一份；每个对话保留最近 {0} 轮，所有检查点合计超过 {1} 时先清理最旧的。": "각 턴이 시작되고 끝날 때 작업 공간의 파일을 기록해 이전 상태로 돌아갈 수 있게 합니다. 내용이 같은 파일은 한 번만 저장되며, 대화마다 최근 {0}턴을 보관합니다. 모든 체크포인트의 합계가 {1}를 넘으면 오래된 것부터 정리됩니다.",
