  "清理会合并重复文件，并删除超出保留数量的旧检查点和不再被引用的文件。被删除的检查点无法再回退。": "정리하면 중복된 파일을 합치고, 보관 한도를 넘은 오래된 체크포인트와 더 이상 참조되지 않는 파일을 삭제합니다. 삭제된 체크포인트로는 되돌릴 수 없습니다.",
  "已释放 {0}，移除了 {1} 个旧检查点。": "{0}를 확보했고 오래된 체크포인트 {1}개를 삭제했습니다.",
