  "Agent 会在独立的工作树里修改并本地提交。它不会推送，也不会回复；这两步要等你检查后再确认。": "에이전트는 별도의 워크트리에서 수정하고 로컬에 커밋합니다. 푸시와 답글은 하지 않으며, 이 두 단계는 검토한 뒤 직접 승인합니다.",
